pub unsafe extern "C" fn tpchq22vgens_state_release(s: *const State) {
    if !s.is_null() {
        drop(Arc::from_raw(s));
    }
}

/// Every kept version's state becomes invalid.
#[no_mangle]
pub unsafe extern "C" fn tpchq22vgens_invalidate_all(st: *const QStore) {
    (*st).invalidate_all()
}

/// How many versions are kept.
#[no_mangle]
pub unsafe extern "C" fn tpchq22vgens_version_count(st: *const QStore) -> usize {
    (*st).version_count()
}

